/// Maximum artifact disclosure one observer attachment may request. The
/// ordering is intentional: metadata discloses less than a hash, and a hash
/// discloses less than inline content.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ScopedArtifactContentPolicy {
    MetadataOnly,
    HashOnly,
    Inline,
}

/// Immutable artifact-request ceiling selected by the trusted Rust host at
/// attachment time. This is not native locator or read authority; the artifact
/// mediator must still prove one exact in-scope relation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScopedArtifactAccessPolicy {
    Disabled,
    Bounded {
        max_bytes_per_read: u64,
        maximum_content_policy: ScopedArtifactContentPolicy,
    },
}

impl ScopedArtifactAccessPolicy {
    pub const fn disabled() -> Self {
        Self::Disabled
    }

    pub const fn bounded(
        max_bytes_per_read: u64,
        maximum_content_policy: ScopedArtifactContentPolicy,
    ) -> Self {
        Self::Bounded {
            max_bytes_per_read,
            maximum_content_policy,
        }
    }
}

/// One exact host-approved object locator. The locator is installed during
/// attachment and cannot be replaced by a decoder or by an access call.
#[derive(Clone, PartialEq, Eq)]
pub struct ScopedKnownObjectGrant {
    pub relation_id: String,
    /// Exactly one known-object grant is the attachment's semantic root. Barrier
    /// root presence is derived from that object's admitted state.
    pub scope_root: bool,
    pub access_root: String,
    pub locator_id: String,
    pub root: PathBuf,
    pub relative_path: PathBuf,
}

impl std::fmt::Debug for ScopedKnownObjectGrant {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ScopedKnownObjectGrant")
            .field("relation_id", &self.relation_id)
            .field("scope_root", &self.scope_root)
            .field("access_root", &self.access_root)
            .field("locator_id", &"<redacted>")
            .field("root", &"<redacted>")
            .field("relative_path", &"<redacted>")
            .finish()
    }
}

/// One host-approved absolute root named by selected scoped relations. Native
