    fn prepare_reset(
        &self,
        object_token: u64,
        source: &ScopedSourceObjectIdentity,
        lane_ordinal: u64,
        observed_at: i64,
        phase: ScopedAppendDeliveryPhase,
        reset: ScopedAppendReset,
    ) -> Result<ScopedProjectionPlan, ScopedProjectionError> {
        let (retracted, fact_ids) = self.prepare_usage_v2_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedUsageV2RetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let context_retractions = self.prepare_actor_context_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let artifact_evidence = self.artifact_evidence.prepare_object_retractions(
            object_token,
            reset.old_generation,
            ScopedProjectionError::InvalidResetState,
        )?;
        let (user_input_projected, user_input_retractions) = self.prepare_user_input_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let (message_projected, message_retractions) = self.prepare_message_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let (plan_projected, plan_retractions) = self.prepare_plan_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let (task_projected, task_retractions) = self.prepare_task_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let (tool_projected, tool_retractions) = self.prepare_tool_retractions(
            object_token,
            reset.old_generation,
            ScopedRetractionDelivery {
                lane_ordinal,
                observed_at,
                phase: ScopedAppendDeliveryPhase::Correction,
            },
            ScopedRevisionedEntityRetractionCause::Reset(reset),
            ScopedProjectionError::InvalidResetState,
        )?;
        let (effective_state_projected, effective_state_retractions) = self
            .prepare_effective_state_retractions(
                object_token,
                reset.old_generation,
                ScopedRetractionDelivery {
                    lane_ordinal,
                    observed_at,
                    phase: ScopedAppendDeliveryPhase::Correction,
                },
                ScopedRevisionedEntityRetractionCause::Reset(reset),
                ScopedProjectionError::InvalidResetState,
            )?;
        let mut projected = Vec::with_capacity(
            retracted
                .len()
                .saturating_add(context_retractions.projected.len())
                .saturating_add(user_input_projected.len())
                .saturating_add(message_projected.len())
                .saturating_add(plan_projected.len())
                .saturating_add(task_projected.len())
                .saturating_add(tool_projected.len())
                .saturating_add(effective_state_projected.len())
                .saturating_add(1),
        );
        projected.push(ScopedProjectedObservation::SourceReset {
            object_token,
            source: source.clone(),
            lane_ordinal,
            observed_at,
            phase,
            event_id: source_reset_event_id(source, reset),
            reset,
        });
        projected.extend(retracted);
        projected.extend(context_retractions.projected);
        projected.extend(user_input_projected);
        projected.extend(message_projected);
        projected.extend(plan_projected);
        projected.extend(task_projected);
        projected.extend(tool_projected);
        projected.extend(effective_state_projected);
        Ok(ScopedProjectionPlan {
            projected,
            mutation: ScopedProjectionMutation {
                usage_retractions: fact_ids,
                actor_retractions: context_retractions.actors,
                affiliation_retractions: context_retractions.affiliations,
                user_input_retractions,
                message_retractions,
                plan_retractions,
                task_retractions,
                tool_retractions,
                effective_state_retractions,
                artifact_evidence,
                ..ScopedProjectionMutation::default()
            },
        })
    }

    fn prepare_presence(
        &self,
        object_token: u64,
        source: &ScopedSourceObjectIdentity,
        lane_ordinal: u64,
        observed_at: i64,
        phase: ScopedAppendDeliveryPhase,
        change: ScopedAppendPresenceChange,
    ) -> Result<ScopedProjectionPlan, ScopedProjectionError> {
        let (retracted, fact_ids) = match change {
            ScopedAppendPresenceChange::Created { .. } => {
                if self
                    .usage_v2
                    .values()
                    .any(|state| state.object_token == object_token)
                    || self
                        .actor_runs
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .actor_affiliations
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .user_input_requests
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .messages
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .plans
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .tasks
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .tools
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self
                        .effective_states
                        .values()
                        .any(|state| state.object_token == object_token)
                    || self.artifact_evidence.has_object(object_token)
                {
                    return Err(ScopedProjectionError::InvalidPresenceState);
                }
                (Vec::new(), Vec::new())
            }
            ScopedAppendPresenceChange::Deleted { generation } => self
                .prepare_usage_v2_retractions(
                    object_token,
                    generation,
                    ScopedRetractionDelivery {
                        lane_ordinal,
                        observed_at,
                        phase,
                    },
                    ScopedUsageV2RetractionCause::SourceDeleted { generation },
                    ScopedProjectionError::InvalidPresenceState,
                )?,
        };
        let context_retractions = match change {
            ScopedAppendPresenceChange::Created { .. } => ScopedActorContextRetractions {
                projected: Vec::new(),
                actors: Vec::new(),
                affiliations: Vec::new(),
            },
            ScopedAppendPresenceChange::Deleted { generation } => self
                .prepare_actor_context_retractions(
                    object_token,
                    generation,
                    ScopedRetractionDelivery {
                        lane_ordinal,
                        observed_at,
                        phase,
                    },
                    ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                    ScopedProjectionError::InvalidPresenceState,
                )?,
        };
        let artifact_evidence = match change {
            ScopedAppendPresenceChange::Created { .. } => {
                artifact_evidence::ScopedArtifactEvidenceMutation::default()
            }
            ScopedAppendPresenceChange::Deleted { generation } => {
                self.artifact_evidence.prepare_object_retractions(
                    object_token,
                    generation,
                    ScopedProjectionError::InvalidPresenceState,
                )?
            }
        };
        let (user_input_projected, user_input_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self
                .prepare_user_input_retractions(
                    object_token,
                    generation,
                    ScopedRetractionDelivery {
                        lane_ordinal,
                        observed_at,
                        phase,
                    },
                    ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                    ScopedProjectionError::InvalidPresenceState,
                )?,
        };
        let (message_projected, message_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self
                .prepare_message_retractions(
                    object_token,
                    generation,
                    ScopedRetractionDelivery {
                        lane_ordinal,
                        observed_at,
                        phase,
                    },
                    ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                    ScopedProjectionError::InvalidPresenceState,
                )?,
        };
        let (plan_projected, plan_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self.prepare_plan_retractions(
                object_token,
                generation,
                ScopedRetractionDelivery {
                    lane_ordinal,
                    observed_at,
                    phase,
                },
                ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                ScopedProjectionError::InvalidPresenceState,
            )?,
        };
        let (task_projected, task_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self.prepare_task_retractions(
                object_token,
                generation,
                ScopedRetractionDelivery {
                    lane_ordinal,
                    observed_at,
                    phase,
                },
                ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                ScopedProjectionError::InvalidPresenceState,
            )?,
        };
        let (tool_projected, tool_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self.prepare_tool_retractions(
                object_token,
                generation,
                ScopedRetractionDelivery {
                    lane_ordinal,
                    observed_at,
                    phase,
                },
                ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                ScopedProjectionError::InvalidPresenceState,
            )?,
        };
        let (effective_state_projected, effective_state_retractions) = match change {
            ScopedAppendPresenceChange::Created { .. } => (Vec::new(), Vec::new()),
            ScopedAppendPresenceChange::Deleted { generation } => self
                .prepare_effective_state_retractions(
                    object_token,
                    generation,
                    ScopedRetractionDelivery {
                        lane_ordinal,
                        observed_at,
                        phase,
                    },
                    ScopedRevisionedEntityRetractionCause::SourceDeleted { generation },
                    ScopedProjectionError::InvalidPresenceState,
                )?,
        };
        let mut projected = Vec::with_capacity(
            retracted
                .len()
                .saturating_add(context_retractions.projected.len())
                .saturating_add(user_input_projected.len())
                .saturating_add(message_projected.len())
                .saturating_add(plan_projected.len())
                .saturating_add(task_projected.len())
                .saturating_add(tool_projected.len())
                .saturating_add(effective_state_projected.len())
                .saturating_add(1),
        );
        projected.push(ScopedProjectedObservation::SourcePresence {
            object_token,
            source: source.clone(),
            lane_ordinal,
            observed_at,
            phase,
            event_id: source_presence_event_id(source, change),
            change,
        });
        projected.extend(retracted);
        projected.extend(context_retractions.projected);
        projected.extend(user_input_projected);
        projected.extend(message_projected);
        projected.extend(plan_projected);
        projected.extend(task_projected);
        projected.extend(tool_projected);
        projected.extend(effective_state_projected);
        Ok(ScopedProjectionPlan {
            projected,
            mutation: ScopedProjectionMutation {
                usage_retractions: fact_ids,
                actor_retractions: context_retractions.actors,
                affiliation_retractions: context_retractions.affiliations,
                user_input_retractions,
                message_retractions,
                plan_retractions,
                task_retractions,
                tool_retractions,
                effective_state_retractions,
                artifact_evidence,
                ..ScopedProjectionMutation::default()
            },
        })
    }

    fn prepare_actor_context_retractions(
        &self,
        object_token: u64,
        generation: u64,
        delivery: ScopedRetractionDelivery,
        cause: ScopedRevisionedEntityRetractionCause,
        mismatch_error: ScopedProjectionError,
    ) -> Result<ScopedActorContextRetractions, ScopedProjectionError> {
        if self
            .actor_runs
            .values()
            .any(|state| state.object_token == object_token && state.generation != generation)
            || self
                .actor_affiliations
                .values()
                .any(|state| state.object_token == object_token && state.generation != generation)
        {
            return Err(mismatch_error);
        }
        let actors = self
            .actor_runs
            .iter()
            .filter_map(|(actor_run, state)| {
                (state.object_token == object_token && state.generation == generation)
                    .then_some(*actor_run)
            })
            .collect::<Vec<_>>();
        let affiliations = self
            .actor_affiliations
            .iter()
            .filter_map(|(affiliation, state)| {
                (state.object_token == object_token && state.generation == generation)
                    .then_some(*affiliation)
            })
            .collect::<Vec<_>>();
        let actor_contexts = self.actor_context_index(&BTreeMap::new(), &BTreeMap::new())?;
        let mut projected = Vec::with_capacity(actors.len().saturating_add(affiliations.len()));
        if self.families.actor_affiliation {
            for affiliation in &affiliations {
                let state = self
                    .actor_affiliations
                    .get(affiliation)
                    .expect("retraction keys came from the same affiliation reducer map");
                let (_, context) = actor_contexts
                    .affiliations
                    .get(&state.revision.actor_run)
                    .ok_or(ScopedProjectionError::InvalidActorContext)?;
                projected.push(ScopedProjectedObservation::ActorAffiliation {
                    lane_ordinal: delivery.lane_ordinal,
                    event: Box::new(ScopedActorAffiliationEvent {
                        event_id: revisioned_entity_event_id(
                            b"runtime.actor-affiliation",
                            ScopedRevisionedEntityOperation::Retract,
                            &state.semantic,
                            Some(cause),
                        ),
                        semantic_revision_ref: state.semantic.semantic_revision_ref,
                        fact_id: state.semantic.fact_id,
                        operation: ScopedRevisionedEntityOperation::Retract,
                        phase: delivery.phase,
                        observed_at: delivery.observed_at,
                        source: state.source.clone(),
                        retraction: Some(cause),
                        actor: actor_contexts
                            .actors
                            .get(&state.revision.actor_run)
                            .cloned(),
                        context: context.clone(),
                        revision: state.revision.clone(),
                    }),
                });
            }
        }
        if self.families.actor_run {
            for actor_run in &actors {
                let state = self
                    .actor_runs
                    .get(actor_run)
                    .expect("retraction keys came from the same actor reducer map");
                let actor = actor_contexts
                    .actors
                    .get(actor_run)
                    .cloned()
                    .ok_or(ScopedProjectionError::InvalidActorContext)?;
                let affiliations = actor_contexts.affiliations.get(actor_run).map_or_else(
                    || unknown_actor_affiliation_context(*actor_run),
                    |(_, context)| context.clone(),
                );
                projected.push(ScopedProjectedObservation::ActorRun {
                    lane_ordinal: delivery.lane_ordinal,
                    event: Box::new(ScopedActorRunEvent {
                        event_id: revisioned_entity_event_id(
                            b"runtime.actor-run",
                            ScopedRevisionedEntityOperation::Retract,
                            &state.semantic,
                            Some(cause),
                        ),
                        semantic_revision_ref: state.semantic.semantic_revision_ref,
                        fact_id: state.semantic.fact_id,
                        operation: ScopedRevisionedEntityOperation::Retract,
                        phase: delivery.phase,
                        observed_at: delivery.observed_at,
                        source: state.source.clone(),
                        retraction: Some(cause),
                        actor,
                        affiliations,
                        revision: state.revision.clone(),
                    }),
                });
            }
        }
        Ok(ScopedActorContextRetractions {
            projected,
            actors,
            affiliations,
        })
    }

    fn prepare_usage_v2_retractions(
        &self,
        object_token: u64,
        generation: u64,
        delivery: ScopedRetractionDelivery,
        cause: ScopedUsageV2RetractionCause,
        mismatch_error: ScopedProjectionError,
    ) -> Result<(Vec<ScopedProjectedObservation>, Vec<CanonicalFactId>), ScopedProjectionError>
    {
        if self
            .usage_v2
            .values()
            .any(|state| state.object_token == object_token && state.generation != generation)
        {
            return Err(mismatch_error);
        }
        let fact_ids = self
            .usage_v2
            .iter()
            .filter_map(|(fact_id, state)| {
                (state.object_token == object_token && state.generation == generation)
                    .then_some(*fact_id)
            })
            .collect::<Vec<_>>();
        let actor_contexts = self.actor_context_index(&BTreeMap::new(), &BTreeMap::new())?;
        let mut projected = Vec::with_capacity(fact_ids.len());
        for fact_id in &fact_ids {
            let state = self
                .usage_v2
                .get(fact_id)
                .expect("retraction keys came from the same reducer map");
            let (actor, affiliations) = actor_contexts.for_usage(&state.revision)?;
            projected.push(ScopedProjectedObservation::UsageV2 {
                lane_ordinal: delivery.lane_ordinal,
                event: Box::new(ScopedUsageV2Event {
                    event_id: usage_v2_event_id(
                        ScopedUsageV2Operation::Retract,
                        &state.semantic,
                        Some(cause),
                    ),
                    semantic_revision_ref: state.semantic.semantic_revision_ref,
                    fact_id: state.semantic.fact_id,
                    operation: ScopedUsageV2Operation::Retract,
                    phase: delivery.phase,
                    observed_at: delivery.observed_at,
                    source: state.source.clone(),
                    retraction: Some(cause),
                    actor,
                    affiliations,
                    revision: state.revision.clone(),
                }),
            });
        }
        Ok((projected, fact_ids))
    }

