    #[test]
    fn capability_report_is_bound_into_completion_and_cannot_cross_family_manifests() {
        let root = root_identity();
        let selection = observation_contract_selection();
        let exact = observation_capabilities_for_selection(&selection);
        let range = observation_capabilities_for_selection_and_compatibility(
            &selection,
            crate::adapter::CompatibilityClass::RangeSupported,
        );
        let alternate_release = observation_capabilities_for_selection_and_context(
            &selection,
            crate::adapter::CompatibilityClass::ExactSupported,
            "fixture-support-v2",
        );
        let manifest = fixture_manifest_for_selection(&selection);
        let scope_coverage = fixture_scope_coverage(&root, true);
        let source_coverage = fixture_completion_coverage(&root, true);
        let artifact_availability = empty_artifact_availability(&root);

        let exact_digest = replacement_snapshot_digest(fixture_completion_components(
            &root,
            true,
            &exact,
            &manifest,
            &scope_coverage,
            &source_coverage,
            &artifact_availability,
        ))
        .unwrap();
        let range_digest = replacement_snapshot_digest(fixture_completion_components(
            &root,
            true,
            &range,
            &manifest,
            &scope_coverage,
            &source_coverage,
            &artifact_availability,
        ))
        .unwrap();
        assert_ne!(exact_digest, range_digest);
        assert!(replacement_snapshot_digest(fixture_completion_components(
            &root,
            true,
            &alternate_release,
            &manifest,
            &scope_coverage,
            &source_coverage,
            &artifact_availability,
        ))
        .is_err());
        let mut alternate_source_coverage = source_coverage.clone();
        for coverage in &mut alternate_source_coverage {
            coverage.scope.support_release_id = "fixture-support-v2".to_owned();
        }
        let alternate_release_digest = replacement_snapshot_digest(fixture_completion_components(
            &root,
            true,
            &alternate_release,
            &manifest,
            &scope_coverage,
            &alternate_source_coverage,
            &artifact_availability,
        ))
        .unwrap();
        assert_ne!(exact_digest, alternate_release_digest);

        let decode_only = vec![fixture_decode_coverage(&root, true)];
        assert!(replacement_snapshot_digest(fixture_completion_components(
            &root,
            true,
            &exact,
            &manifest,
            &scope_coverage,
            &decode_only,
            &artifact_availability,
        ))
        .is_err());

        let multi_selection = multi_family_observation_contract_selection();
        let multi_capabilities = observation_capabilities_for_selection(&multi_selection);
        assert!(
            completion_capability_digest(&multi_capabilities, &manifest, &source_coverage,)
                .is_err()
        );
        let multi_manifest = fixture_manifest_for_selection(&multi_selection);
        let multi_coverage =
            fixture_completion_coverage_for_selection(&root, true, &multi_selection);
        let mut reversed_manifest = multi_manifest.clone();
        reversed_manifest.reverse();
        assert!(completion_capability_digest(
            &multi_capabilities,
            &reversed_manifest,
            &multi_coverage,
        )
        .is_err());
        let mut reversed_capabilities = multi_capabilities.clone();
        reversed_capabilities.fact_families.reverse();
        assert!(completion_capability_digest(
            &reversed_capabilities,
            &multi_manifest,
            &multi_coverage,
        )
        .is_err());

        let mut delivery = delivery_lane(1, 1);
        let before = delivery.state();
        let watermark = ScopedObservationWatermarkCore {
            attachment_authority: next_scoped_attachment_authority().unwrap(),
            root: root.clone(),
            scope_epoch: SCOPED_INITIAL_SCOPE_EPOCH,
            offered_through_sequence: 0,
            source_coverage,
            observation_capabilities: multi_capabilities,
            scope_coverage,
            explicit_object_errors: Vec::new(),
            artifact_availability,
            queue_state: before,
        };
        assert_eq!(
            delivery.offer_bootstrap_barrier(&root, watermark, manifest, true, 50),
            Err(ScopedBootstrapBarrierError::InvalidSnapshot)
        );
        assert_eq!(delivery.state(), before);
        assert!(delivery.bootstrap_barrier().is_none());

        let exact_manifest = fixture_manifest_for_selection(&selection);
        let exact_watermark = ScopedObservationWatermarkCore {
            attachment_authority: next_scoped_attachment_authority().unwrap(),
            root: root.clone(),
            scope_epoch: SCOPED_INITIAL_SCOPE_EPOCH,
            offered_through_sequence: 0,
            source_coverage: fixture_completion_coverage(&root, true),
            observation_capabilities: exact,
            scope_coverage: fixture_scope_coverage(&root, true),
            explicit_object_errors: Vec::new(),
            artifact_availability: empty_artifact_availability(&root),
            queue_state: before,
        };
        let barrier = delivery
            .offer_bootstrap_barrier(&root, exact_watermark, exact_manifest, true, 51)
            .unwrap();
        assert!(bootstrap_barrier_snapshot_is_valid(&barrier));
        let mut forged = (*barrier).clone();
        forged.observation_capabilities = range;
        assert!(!bootstrap_barrier_snapshot_is_valid(&forged));
    }

    #[test]
    fn actor_replacement_digests_are_canonical_and_exclude_delivery_time() {
        let early_record = record_with_observed_at(3, 0, 10, 44);
        let late_record = record_with_observed_at(3, 0, 10, 99);
        let mut forward = sink(8);
        assert!(forward
            .project(&decoded_frame(
                1,
                ScopedAppendDeliveryPhase::Bootstrap,
                &early_record,
                multi_actor_context_batch(&early_record, false),
            ))
            .unwrap()
            .is_empty());
        let mut reverse = sink(8);
        assert!(reverse
            .project(&decoded_frame(
                9,
                ScopedAppendDeliveryPhase::Correction,
                &late_record,
                multi_actor_context_batch(&late_record, true),
            ))
            .unwrap()
            .is_empty());

        let forward_actors = forward
            .actor_run_replacement_snapshot(ScopedAppendDeliveryPhase::Bootstrap)
            .unwrap();
        let reverse_actors = reverse
            .actor_run_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
            .unwrap();
        let forward_affiliations = forward
            .actor_affiliation_replacement_snapshot(ScopedAppendDeliveryPhase::Bootstrap)
            .unwrap();
        let reverse_affiliations = reverse
            .actor_affiliation_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
            .unwrap();
        assert_eq!(forward_actors.entity_count, 2);
        assert_eq!(forward_affiliations.entity_count, 2);
        assert_eq!(
            bytes_hex(forward_actors.semantic_digest.as_bytes()),
            "4ae181a02b5eda5a9bf5711cd3d0af2277b52fca3fe7d30eb23f59ce330605d6"
        );
        assert_eq!(
            bytes_hex(forward_affiliations.semantic_digest.as_bytes()),
            "47d03bdf40c4dab51293ab4e1fa16fc72169d66382274bfdf6fd8fba4483f668"
        );
        assert_eq!(
            forward_actors.semantic_digest,
            reverse_actors.semantic_digest
        );
        assert_eq!(
            forward_affiliations.semantic_digest,
            reverse_affiliations.semantic_digest
        );
        assert!(forward_actors
            .entities
            .windows(2)
            .all(|entities| entities[0].revision.actor_run < entities[1].revision.actor_run));
        assert!(forward_affiliations
            .entities
            .windows(2)
            .all(|entities| entities[0].revision.affiliation < entities[1].revision.affiliation));
        assert_ne!(
            forward_actors.entities[0].source.provenance.observed_at,
            reverse_actors.entities[0].source.provenance.observed_at
        );
        assert_ne!(forward_actors.phase, reverse_actors.phase);
    }

    #[test]
    fn actor_replacement_snapshots_remove_reset_and_deleted_owners() {
        for lifecycle in ["reset", "delete"] {
            let mut projection = sink(8);
            let source_record = record(1, 0, 10);
            assert!(projection
                .project(&decoded_frame(
                    1,
                    ScopedAppendDeliveryPhase::Bootstrap,
                    &source_record,
                    contextual_usage_batch(
                        &source_record,
                        None,
                        true,
                        &[ActorAffiliationDimension::Team],
                    ),
                ))
                .unwrap()
                .is_empty());
            let populated_actor = projection
                .actor_run_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            let populated_affiliation = projection
                .actor_affiliation_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            assert_eq!(populated_actor.entity_count, 1);
            assert_eq!(populated_affiliation.entity_count, 1);

            let control = if lifecycle == "reset" {
                ScopedQueuedObservationFrame::Reset {
                    object_token: OBJECT_TOKEN,
                    source: source_identity(),
                    lane_ordinal: 2,
                    observed_at: 45,
                    phase: ScopedAppendDeliveryPhase::Correction,
                    reset: ScopedAppendReset {
                        old_generation: 1,
                        new_generation: 2,
                        reason: AppendTransition::Truncated,
                    },
                }
            } else {
                ScopedQueuedObservationFrame::Presence {
                    object_token: OBJECT_TOKEN,
                    source: source_identity(),
                    lane_ordinal: 2,
                    observed_at: 45,
                    phase: ScopedAppendDeliveryPhase::Correction,
                    change: ScopedAppendPresenceChange::Deleted { generation: 1 },
                }
            };
            assert_eq!(projection.project(&control).unwrap().len(), 1);
            let actor = projection
                .actor_run_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            let affiliation = projection
                .actor_affiliation_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            let empty = sink(8);
            let empty_actor = empty
                .actor_run_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            let empty_affiliation = empty
                .actor_affiliation_replacement_snapshot(ScopedAppendDeliveryPhase::Correction)
                .unwrap();
            assert_eq!(actor, empty_actor);
            assert_eq!(affiliation, empty_affiliation);
            assert_ne!(actor.semantic_digest, populated_actor.semantic_digest);
            assert_ne!(
                affiliation.semantic_digest,
                populated_affiliation.semantic_digest
            );
        }
    }

    #[test]
    fn actor_context_mismatch_and_capacity_fail_atomically() {
        let mismatched_record = record(3, 0, 10);
        let mut mismatched_batch =
            FactBatch::new_with_semantic_context(8, 4, semantic_context()).unwrap();
        mismatched_batch
            .push_native(
                &mismatched_record,
                b"native-run",
                Fact::ActorRunRevision(actor_run_fact_for(
                    &mismatched_batch,
                    "foreign-session",
                    "native-run",
                )),
            )
            .unwrap();
        let usage = usage_fact(&mismatched_batch, "response-1", 10);
        let revision_key = usage.semantic_revision_key().unwrap();
        mismatched_batch
            .push_native_object_scoped_with_revision(
                &mismatched_record,
                b"response-1",
                &revision_key,
                Fact::UsageRevisionV2(usage),
            )
            .unwrap();
        let mut mismatched = sink(8);
        assert_eq!(
            mismatched.project(&decoded_frame(
                1,
                ScopedAppendDeliveryPhase::Live,
                &mismatched_record,
                mismatched_batch,
            )),
            Err(ScopedProjectionError::InvalidActorContext)
        );
        assert!(mismatched.usage_v2.is_empty());
        assert!(mismatched.actor_runs.is_empty());
        assert!(mismatched.actor_affiliations.is_empty());

        let mut bounded = sink(1);
        let first_record = record(3, 0, 10);
        let first = only_usage_event(
            bounded
                .project(&decoded_frame(
                    1,
                    ScopedAppendDeliveryPhase::Live,
                    &first_record,
                    contextual_usage_batch(
                        &first_record,
                        Some(("response-1", 10)),
                        true,
                        &[ActorAffiliationDimension::Team],
                    ),
                ))
                .unwrap(),
        );

        let second_actor_record = record(3, 10, 20);
        let mut second_actor_batch =
            FactBatch::new_with_semantic_context(2, 1, semantic_context()).unwrap();
        second_actor_batch
            .push_native(
                &second_actor_record,
                b"native-run-2",
                Fact::ActorRunRevision(actor_run_fact_for(
                    &second_actor_batch,
                    "native-session",
                    "native-run-2",
                )),
            )
            .unwrap();
        assert_eq!(
            bounded.project(&decoded_frame(
                2,
                ScopedAppendDeliveryPhase::Live,
                &second_actor_record,
                second_actor_batch,
            )),
            Err(ScopedProjectionError::ActorRunCapacityFull)
        );

        let second_affiliation_record = record(3, 20, 30);
        let mut second_affiliation_batch =
            FactBatch::new_with_semantic_context(2, 1, semantic_context()).unwrap();
        let workflow = affiliation_fact(
            &second_affiliation_batch,
            ActorAffiliationDimension::Workflow,
        );
        let stable_key = *workflow.affiliation.as_bytes();
        second_affiliation_batch
            .push_native(
                &second_affiliation_record,
                &stable_key,
                Fact::ActorAffiliationRevision(workflow),
            )
            .unwrap();
        assert_eq!(
            bounded.project(&decoded_frame(
                3,
                ScopedAppendDeliveryPhase::Live,
                &second_affiliation_record,
                second_affiliation_batch,
            )),
            Err(ScopedProjectionError::ActorAffiliationCapacityFull)
        );
        assert_eq!(bounded.usage_v2.len(), 1);
        assert_eq!(bounded.actor_runs.len(), 1);
        assert_eq!(bounded.actor_affiliations.len(), 1);
        assert_eq!(
            bounded.usage_v2_revision(&first.fact_id),
            Some(first.semantic_revision_ref)
        );
    }

    #[test]
    fn actor_context_exact_repeat_cannot_change_object_owner() {
        let record = record(3, 0, 10);
        let actor_batch = || {
            let mut batch = FactBatch::new_with_semantic_context(2, 1, semantic_context()).unwrap();
            let actor = actor_run_fact(&batch);
            batch
                .push_native(&record, b"native-run", Fact::ActorRunRevision(actor))
                .unwrap();
            batch
        };
        let frame = |object_token, batch| ScopedQueuedObservationFrame::Decoded {
            object_token,
            source: source_identity(),
            lane_ordinal: object_token,
            phase: ScopedAppendDeliveryPhase::Live,
            item: Box::new(ScopedDecodedAppendItem::Record {
                evidence: Box::new(scoped_record_evidence(&record, RawRetentionPolicy::None)),
                disposition: DecodeDisposition::Applied,
                batch,
                quarantined: false,
            }),
        };

        let mut projection = sink(8);
        assert!(projection
            .project(&frame(OBJECT_TOKEN, actor_batch()))
            .unwrap()
            .is_empty());
        assert_eq!(projection.actor_runs.len(), 1);
        assert_eq!(
            projection.project(&frame(OBJECT_TOKEN + 1, actor_batch())),
            Err(ScopedProjectionError::ConflictingOwnership)
        );
        assert_eq!(projection.actor_runs.len(), 1);
    }

    #[test]
    fn scoped_envelope_mapper_routes_typed_usage_without_exposing_internal_ordinals() {
        let root = root_identity();
        let selection = observation_contract_selection();
        let mapper = ScopedObservationEnvelopeMapper::new(root.clone(), selection.clone());
        let record = record(3, 10, 25);
        let frame = decoded_frame(
            7,
            ScopedAppendDeliveryPhase::Live,
            &record,
            usage_batch(&record, "response-1", 10, None),
        );
        let mut projection = sink(8);
        let projected = projection.project(&frame).unwrap();
        let mut delivery = delivery_lane(1, 1);
        delivery.offer(projected).unwrap();
        let delivered = delivery.pop_next().unwrap();
        let expected_event_id = delivered.event_id;
        let expected_semantic_ref = delivered.semantic_revision_ref;
        let mut wrong_event_contract = delivered.clone();
        wrong_event_contract.event_contract_version += 1;
        assert_eq!(
            mapper.map(wrong_event_contract),
            Err(ScopedEnvelopeError::DeliveryMismatch)
        );
        let unselected_mapper = ScopedObservationEnvelopeMapper::new(
            root.clone(),
            observation_contract_selection_for("runtime.actor-run"),
        );
        assert_eq!(
            unselected_mapper.map(delivered.clone()),
            Err(ScopedEnvelopeError::EventFamilyNotSelected)
        );
        let envelope = mapper.map(delivered).unwrap();

        assert_eq!(
            envelope.contract_version,
            selection.envelope_contract_version
        );
        assert_eq!(envelope.contract_selection, selection);
        assert_eq!(envelope.observer_sequence, 1);
        assert_eq!(envelope.scope_epoch, SCOPED_INITIAL_SCOPE_EPOCH);
        assert_eq!(envelope.event_id, expected_event_id);
        assert_eq!(envelope.semantic_revision_ref, expected_semantic_ref);
        assert_eq!(envelope.root.session_key, root.session_key);
        assert_eq!(envelope.root.session_ref, root.session_ref);
        assert_eq!(
            envelope
                .root
                .native_session_claim
                .as_ref()
                .unwrap()
                .entity_ref,
            root.session_ref
        );
        assert_eq!(envelope.actor.root_session_key, root.session_key);
        assert_ne!(envelope.actor.run_key, root.root_actor_run_key);
        assert_eq!(envelope.actor.role, ActorRunRole::Child);
        assert_eq!(envelope.actor.parent_run_key, None);
        assert_eq!(
            envelope.actor.native_session_id.as_deref(),
            Some("native-session")
        );
        assert_eq!(
            envelope.actor_attribution,
            ScopedActorAttribution::DerivedExact
        );
        assert_eq!(
            envelope.affiliations.completeness,
            ContractCompleteness::Unknown
        );
        assert!(envelope.affiliations.derived_from_revision_refs.is_empty());
        assert_eq!(envelope.source.instance_key, root.source_instance_key);
        assert_eq!(envelope.source.generation, 3);
        assert_eq!(envelope.source.record_index, Some(0));
        assert_eq!(
            envelope.source.byte_range,
            Some(ScopedObservationByteRange { start: 10, end: 25 })
        );
        assert_eq!(envelope.observed_at, 44);
        assert_eq!(
            envelope
                .native_time
                .as_ref()
                .map(|value| value.value.as_str()),
            Some("2026-08-16T00:00:00Z")
        );
        assert_eq!(
            envelope.evidence.authority,
            ScopedEnvelopeEvidenceAuthority::NativeRecord
        );
        assert_eq!(envelope.evidence.quality, QualifiedValueQuality::Exact);
        assert!(matches!(
            envelope.native_evidence,
            ScopedNativeEvidence::Withheld {
                reason: ScopedNativeEvidenceWithheldReason::ProjectionBoundary,
                ..
            }
        ));
        assert!(matches!(
            envelope.event,
            ScopedObservationEvent::UsageV2 {
                operation: ScopedUsageV2Operation::Upsert,
                ..
            }
        ));
    }

    #[test]
    fn scoped_envelope_mapper_marks_controls_as_fallback_and_retractions_with_control_time() {
        let root = root_identity();
        let mapper = envelope_mapper(root.clone());
        let record = record_with_observed_at(1, 0, 10, 44);
        let frame = decoded_frame(
            1,
            ScopedAppendDeliveryPhase::Bootstrap,
            &record,
            usage_batch(&record, "response-1", 10, None),
        );
        let mut projection = sink(8);
        only_usage_event(projection.project(&frame).unwrap());

        let reset = ScopedAppendReset {
            old_generation: 1,
            new_generation: 2,
            reason: AppendTransition::Truncated,
        };
        let reset_frame = ScopedQueuedObservationFrame::Reset {
            object_token: OBJECT_TOKEN,
            source: source_identity(),
            lane_ordinal: 2,
            observed_at: 777,
            phase: ScopedAppendDeliveryPhase::Correction,
            reset,
        };
        let projected = projection.project(&reset_frame).unwrap();
        let mut delivery = delivery_lane(1, 1);
        delivery.offer(projected).unwrap();

        let control = mapper.map(delivery.pop_next().unwrap()).unwrap();
        assert_eq!(control.actor.run_key, root.root_actor_run_key);
        assert_eq!(control.actor.role, ActorRunRole::Root);
        assert_eq!(
            control.actor_attribution,
            ScopedActorAttribution::ScopeFallback {
                reason: ScopedActorFallbackReason::SourceLifecycleControl,
            }
        );
        assert_eq!(control.semantic_revision_ref, None);
        assert_eq!(control.source.generation, 2);
        assert_eq!(control.observed_at, 777);
        assert_eq!(
            control.evidence.authority,
            ScopedEnvelopeEvidenceAuthority::EngineControl
        );
        assert!(matches!(
            control.event,
            ScopedObservationEvent::SourceReset { reset: value } if value == reset
        ));

        let retraction = mapper.map(delivery.pop_next().unwrap()).unwrap();
        assert_ne!(retraction.actor.run_key, root.root_actor_run_key);
        assert_eq!(retraction.actor.role, ActorRunRole::Child);
        assert_eq!(
            retraction.actor_attribution,
            ScopedActorAttribution::DerivedExact
        );
        assert!(retraction.semantic_revision_ref.is_some());
        assert_eq!(retraction.observed_at, 777);
        assert_eq!(
            retraction.evidence.authority,
            ScopedEnvelopeEvidenceAuthority::CommonReducer
        );
        assert_eq!(retraction.evidence.quality, QualifiedValueQuality::Derived);
        assert!(matches!(
            retraction.event,
            ScopedObservationEvent::UsageV2 {
                operation: ScopedUsageV2Operation::Retract,
                retraction: Some(ScopedUsageV2RetractionCause::Reset(value)),
                ..
            } if value == reset
        ));
        assert!(delivery.is_empty());
    }

